def find(g,q,b,N=16):
 c=1-g;M=[canonical_column(g,a,m,b) for a in range(N+1) for m in(c-q-2-a,c+q+2-a)];K=[current_defect(g,a,q,b) for a in range(b)];rows=sorted({r for z in M+K for r in z});ans=[]
 for ki,k in enumerate(K):
  hit=None
  for w in range(1,min(16,len(rows))+1):
   for i in range(len(rows)-w+1):
    rs=rows[i:i+w];mc=cut(M,rs);kc=cut([k],rs)
    if rank(mc+kc)>rank(mc):hit=(w,rs[0],rs[-1]);break
   if hit:break
  ans.append(hit)
 return ans
